<?php
session_start(); if(!isset($_SESSION['divisi'])||$_SESSION['divisi']!=='akunting'){header('Location: ../index.php');exit;} require_once '../config/database.php';
$search=trim($_GET['search']??''); $limit=100;
$sql="SELECT t.id,t.berat_kg,t.total_upah,t.created_at,k.nama_lengkap,k.barcode_uid,mt.nama_pekerjaan,mt.harga_per_satuan,a.username FROM transaksi_timbang t LEFT JOIN karyawan k ON t.karyawan_id=k.id LEFT JOIN master_tarif mt ON t.tarif_id=mt.id LEFT JOIN admin_users a ON t.admin_id=a.id";
$params=[]; if($search!==''){ $sql.=" WHERE k.nama_lengkap ILIKE ? OR k.barcode_uid ILIKE ? OR mt.nama_pekerjaan ILIKE ?"; $x='%'.$search.'%';$params=[$x,$x,$x]; } $sql.=" ORDER BY t.created_at DESC LIMIT $limit"; $st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll();
function rp($v){return 'Rp '.number_format((float)$v,0,',','.');} function kg($v){return number_format((float)$v,2,',','.').' kg';}
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Histori Transaksi - Akunting</title><link href="../assets/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f8f9fa}.sidebar{min-height:100vh;background:#fff;border-right:1px solid #ddd}.brand{color:#198754;font-weight:700}.nav-link{color:#555;border-radius:8px;margin:3px 10px}.nav-link:hover,.nav-link.active{background:#198754;color:#fff}.content{padding:25px}.card{border:0;border-radius:12px}</style></head><body><div class="container-fluid"><div class="row"><aside class="col-md-3 col-lg-2 sidebar p-3"><h5 class="brand mb-4">🍤 Pabrik Udang</h5><small class="text-muted px-2">AKUNTING</small><nav class="mt-2"><a class="nav-link" href="dashboard_akunting.php">Dashboard</a><a class="nav-link" href="rekap_produksi.php">Rekap Produksi</a><a class="nav-link" href="rekap_upah.php">Rekap Upah</a><a class="nav-link active" href="histori_produksi_akunting.php">Histori Transaksi</a><a class="nav-link" href="master_tarif.php">Master Tarif</a><a class="nav-link" href="rekap_lembur.php">Rekap Lembur</a><a class="nav-link" href="profil_akunting.php">Profil Akunting</a><a class="nav-link" href="../logout.php">Logout</a></nav></aside><main class="col-md-9 col-lg-10 content"><div class="mb-4"><h3 class="fw-bold">Histori Transaksi Penimbangan</h3><p class="text-muted">Maksimal 100 transaksi terbaru.</p></div><div class="card shadow-sm"><div class="card-body"><form class="row g-2 mb-3"><div class="col-md-10"><input name="search" value="<?=htmlspecialchars($search)?>" class="form-control" placeholder="Cari nama karyawan, barcode, atau pekerjaan..."></div><div class="col-md-2"><button class="btn btn-success w-100">Cari</button></div></form><div class="table-responsive"><table class="table table-hover align-middle"><thead class="table-light"><tr><th>Waktu</th><th>Karyawan</th><th>Pekerjaan</th><th>Berat</th><th>Upah</th><th>Admin</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=date('d/m/Y H:i',strtotime($r['created_at']))?></td><td><b><?=htmlspecialchars($r['nama_lengkap']??'-')?></b><br><small><?=htmlspecialchars($r['barcode_uid']??'-')?></small></td><td><?=htmlspecialchars($r['nama_pekerjaan']??'-')?></td><td><?=kg($r['berat_kg'])?></td><td><?=rp($r['total_upah'])?></td><td><?=htmlspecialchars($r['username']??'-')?></td></tr><?php endforeach;if(!$rows): ?><tr><td colspan="6" class="text-center text-muted py-4">Data tidak ditemukan.</td></tr><?php endif; ?></tbody></table></div></div></div></main></div></div></body></html>
